#[derive(Debug, clap::Args)]
#[clap(alias = "generate")]
pub struct Init {
    /// Overwrite existing hk.pkl file
    #[clap(short, long)]
    force: bool,
    /// Interactive mode: select linters and hooks manually
    #[clap(short, long)]
    interactive: bool,
    /// Generate a mise.toml file with hk configured
    ///
