import "./banner.css";

interface BannerData {
  id: string;
  enabled: boolean;
  message: string;
  link?: string;
  linkText?: string;
  expires?: string;
}

const ENDPOINT = "https://jdx.dev/banner.json";
const STORAGE_KEY = "jdx-banner-dismissed";

export function initBanner(): void {
  if (typeof window === "undefined") return;
  fetch(ENDPOINT)
    .then((r) => (r.ok ? (r.json() as Promise<BannerData>) : null))
    .then((b) => {
      if (!b || !b.enabled) return;
      if (isExpired(b.expires)) return;
      if (localStorage.getItem(STORAGE_KEY) === b.id) return;
      render(b);
    })
    .catch(() => {});
}

function isExpired(expires: string | undefined): boolean {
  if (!expires) return false;
  const t = Date.parse(expires);
  if (Number.isNaN(t)) return false;
  return Date.now() >= t;
}

function isHttpUrl(value: string): boolean {
  try {
    const u = new URL(value, window.location.href);
    return u.protocol === "http:" || u.protocol === "https:";
  } catch {
    return false;
  }
}

function render(b: BannerData): void {
  const el = document.createElement("div");
  el.className = "jdx-banner";
  el.setAttribute("role", "region");
  el.setAttribute("aria-label", "Site announcement");

  const msg = document.createElement("span");
  msg.textContent = b.message;
  el.appendChild(msg);

  if (b.link && isHttpUrl(b.link)) {
    const a = document.createElement("a");
    a.href = b.link;
    a.target = "_blank";
    a.rel = "noopener";
    a.textContent = b.linkText || "Learn more";
    el.appendChild(a);
  }

  const syncHeight = () => {
    document.documentElement.style.setProperty(
      "--vp-layout-top-height",
      `${el.offsetHeight}px`,
    );
  };

  const observer =
    typeof ResizeObserver !== "undefined"
      ? new ResizeObserver(syncHeight)
      : null;

  const btn = document.createElement("button");
  btn.type = "button";
  btn.setAttribute("aria-label", "Dismiss");
  btn.textContent = "\u00d7";
  btn.addEventListener("click", () => {
    localStorage.setItem(STORAGE_KEY, b.id);
    observer?.disconnect();
    el.remove();
    document.documentElement.style.removeProperty("--vp-layout-top-height");
  });
  el.appendChild(btn);

  document.body.prepend(el);

  requestAnimationFrame(syncHeight);
  observer?.observe(el);
}
.jdx-banner {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1001;
  display: flex;
  gap: 0.75rem;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 2.75rem;
  background: var(--vp-c-brand-1, #3abff8);
  color: #000;
  font-size: 0.9rem;
  line-height: 1.4;
  text-align: center;
}
.jdx-banner a {
  color: #000;
  text-decoration: underline;
  font-weight: 600;
}
.jdx-banner button {
  position: absolute;
  right: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: 0;
  color: inherit;
  font-size: 1.25rem;
  cursor: pointer;
  line-height: 1;
  padding: 0 0.5rem;
  opacity: 0.7;
}
.jdx-banner button:hover {
  opacity: 1;
}
@media (max-width: 640px) {
  .jdx-banner {
    flex-direction: column;
    gap: 0.125rem;
    font-size: 0.8rem;
    padding: 0.5rem 2.25rem;
    line-height: 1.3;
    text-wrap: balance;
  }
  .jdx-banner button {
    top: 0.25rem;
    right: 0.25rem;
    transform: none;
  }
}

