                .iter()
                .map(|d| format!("{} ({})", d.builtin.name, d.reason))
                .collect::<Vec<_>>()
                .join(", ");
            println!("Detected: {}", summary);
        }
        println!("Created hk.pkl");

        Ok(())
    }

