/// A custom step using hk's whitespace utility, including check and fix tests.
amends "package://github.com/jdx/hk/releases/download/v1.58.1/hk@1.58.1#/Config.pkl"

import "package://github.com/jdx/hk/releases/download/v1.58.1/hk@1.58.1#/Builtins.pkl"

local linters = new Mapping<String, Step> {
  ["whitespace"] {
    glob = List("*.txt", "*.md")
    check = "hk util trailing-whitespace {{files}}"
    fix = "hk util trailing-whitespace --fix {{files}}"
    tests {
      ["accepts clean text"] {
        run = "check"
        write {
          ["{{tmp}}/clean.txt"] = "hello\n"
        }
        expect { code = 0 }
      }
      ["removes trailing spaces"] {
        run = "fix"
        write {
          ["{{tmp}}/dirty.txt"] = "hello  \n"
        }
        expect {
          files {
            ["{{tmp}}/dirty.txt"] = "hello\n"
          }
        }
      }
    }
  }
  ["newlines"] = Builtins.newlines
}

hooks {
  ["pre-commit"] {
    fix = true
    stash = "git"
    steps = linters
  }
  ["check"] { steps = linters }
  ["fix"] {
    fix = true
    steps = linters
  }
}
use crate::{Result, config::Config};
use indexmap::IndexSet;
use tokio::sync::Semaphore;

/// Run step-defined tests
#[derive(usage_rs::Args)]
pub struct Test {
    /// List tests without running
    #[usage(long)]
    list: bool,

    /// Filter by test name (repeatable)
    #[usage(long, value_name = "NAME", variadic, var_min = 1)]
    name: Vec<String>,

    /// Filter by step name (repeatable)
    #[usage(long, value_name = "STEP", variadic, var_min = 1)]
    step: Vec<String>,
}

impl Test {
    pub async fn run(self) -> Result<()> {
        let cfg = Config::get()?;
        let mut count = 0usize;
        let mut to_run: Vec<(
            String,
            crate::step::Step,
            String,
            crate::step_test::StepTest,
        )> = vec![];
        let mut seen: IndexSet<String> = IndexSet::new();
        for (_hook_name, hook) in cfg.hooks {
            for (step_name, sog) in hook.steps {
                let step = match sog {
                    crate::hook::StepOrGroup::Step(s) => s,
                    crate::hook::StepOrGroup::Group(_) => continue,
                };
                if !self.step.is_empty() && !self.step.contains(&step_name) {
                    continue;
                }
                for (tname, test) in &step.tests {
                    if !self.name.is_empty() && !self.name.contains(tname) {
                        continue;
                    }
                    // Deduplicate identical step+test pairs across hooks
                    let step_sig = serde_json::to_string(&*step).unwrap_or_default();
                    let test_sig = serde_json::to_string(&test).unwrap_or_default();
